for _skill_code, _entries in EXTRA_TASK_BANK.items():
    TASK_BANK[_skill_code].extend(_entries)

def seed_catalog(db: Session) -> dict[str, int]:
    if db.query(models.Skill).count() > 0:
        return {"skills": 0, "tasks": 0, "users": 0, "exams": 0}
    skill_rows: dict[str, models.Skill] = {}
    for order, (code, name, description) in enumerate(SKILLS):
        skill = models.Skill(code=code, name=name, description=description, sort_order=order)
        db.add(skill)
        db.flush()
        skill_rows[code] = skill

    tasks: list[models.Task] = []
    for code, entries in TASK_BANK.items():
        for idx, entry in enumerate(entries):
            question, a, b, c, d, correct, explanation = entry
            skill_index = list(TASK_BANK).index(code)
            progression = idx / max(len(entries) - 1, 1)
            difficulty = round(0.18 + 0.66 * progression + 0.015 * ((skill_index % 3) - 1), 3)
            task = models.Task(
                skill_id=skill_rows[code].id,
                question=question,
                option_a=a,
                option_b=b,
                option_c=c,
                option_d=d,
                correct_option=correct,
                explanation=explanation,
                source_reference="Учебный банк заданий ВКР",
                difficulty=float(min(max(difficulty, 0.15), 0.90)),
                discrimination=round(0.8 + (idx % 4) * 0.15, 2),
                cognitive_level=1 + idx % 3,
                estimated_time_sec=30 + (idx % 5) * 10,
                tags=[code.lower(), f"level-{1 + idx % 3}"],
            )
            db.add(task)
            tasks.append(task)
    db.flush()

    student = models.User(username="student_demo", password_hash=hash_password("1234"), role="student", full_name="Демонстрационный студент")
    teacher = models.User(username="teacher_demo", password_hash=hash_password("1234"), role="teacher", full_name="Демонстрационный преподаватель")
    admin = models.User(username="admin_demo", password_hash=hash_password("1234"), role="admin", full_name="Администратор")
    db.add_all([student, teacher, admin])
    db.flush()

    exam = models.Exam(title="Итоговая диагностика цифровой грамотности", description="Контроль по всем шести компетенциям.", duration_minutes=35, passing_score=0.65, created_by=teacher.id)
    db.add(exam)
    db.flush()
    chosen = [task for i, task in enumerate(tasks) if i % 5 == 0][:12]
    for position, task in enumerate(chosen, start=1):
        db.add(models.ExamTask(exam_id=exam.id, task_id=task.id, position=position, points=1.0))
    db.commit()
    return {"skills": len(SKILLS), "tasks": len(tasks), "users": 3, "exams": 1}


def seed_synthetic_history(db: Session, users: int = 180, attempts_per_user: int = 80) -> int:
    """Create reproducible bootstrap history for local ML demonstration.

    Accounts use the `synthetic_` prefix so generated observations cannot be confused
    with real student data. The generator is not called unless explicitly requested.
    """
    if db.query(models.User).filter(models.User.username.like("synthetic_%")).count() > 0:
        return 0
    settings = get_settings()
    rng = random.Random(settings.random_seed)
    tasks = db.query(models.Task).all()
    if not tasks:
        raise RuntimeError("catalog must be seeded first")
    start = utcnow_naive() - timedelta(days=55)
    created = 0
    disabled_password_hash = hash_password("disabled-demo")
    for uidx in range(users):
        user = models.User(
            username=f"synthetic_{uidx:03d}",
            password_hash=disabled_password_hash,
            role="student",
            group_name=f"SYNTH-{chr(65 + (uidx % 3))}",
            is_active=False,
        )
        db.add(user)
        db.flush()
        base_ability = rng.uniform(0.22, 0.84)
        skill_offsets = {skill.id: rng.gauss(0, 0.11) for skill in db.query(models.Skill).all()}
        current = start + timedelta(days=rng.uniform(0, 10))
        for index in range(attempts_per_user):
            task = rng.choice(tasks)
            practice_gain = min(index / attempts_per_user * 0.18, 0.18)
            ability = min(0.96, max(0.04, base_ability + skill_offsets[task.skill_id] + practice_gain))
            fatigue = -0.07 if index % 17 in {15, 16} else 0.0
            logit = 5.0 * (ability - task.difficulty) + fatigue
            probability = 1.0 / (1.0 + math.exp(-logit))
            correct = rng.random() < probability
            response = int(max(3500, rng.gauss(task.estimated_time_sec * 1000 * (1.25 - 0.55 * ability), 6000)))
            db.add(models.Attempt(
                user_id=user.id,
                task_id=task.id,
                session_id=f"bootstrap-{uidx:03d}",
                selected_option=task.correct_option if correct else rng.choice([x for x in "ABCD" if x != task.correct_option]),
                is_correct=correct,
                predicted_probability=None,
                prediction_model="synthetic-generator",
                response_time_ms=response,
                created_at=current,
                client_context={"source": "synthetic_bootstrap_v2"},
            ))
            current += timedelta(hours=rng.uniform(2, 30))
            created += 1
    db.commit()
    return created
